// hendzzz

(function () {
    const tracks = document.querySelectorAll(".mtrack");

    tracks.forEach((track) => {
        track.innerHTML += track.innerHTML;

        let position = 0;

        let baseSpeed = parseFloat(track.dataset.speed) || 1.5;
        let direction = track.dataset.direction || "up";
        
        // Default: false. Hanya true jika data-hover diset ke string "true"
        let enableHover = (track.dataset.hover || "false").toLowerCase() === "true";

        let speed = baseSpeed;
        let targetSpeed = baseSpeed;

        // Event listener hanya dipasang jika enableHover bernilai true
        if (enableHover) {
            track.addEventListener("mouseenter", () => {
                targetSpeed = 0.15; // Kecepatan saat melambat
            });

            track.addEventListener("mouseleave", () => {
                targetSpeed = baseSpeed;
            });
        }

        function animate() {
            speed += (targetSpeed - speed) * 0.05;

            // Penentuan arah
            if (direction === "up") {
                position -= speed;
            } else {
                position += speed;
            }

            const halfHeight = track.scrollHeight / 2;

            if (direction === "up" && Math.abs(position) >= halfHeight) {
                position += halfHeight;
            }

            if (direction === "down" && position >= 0) {
                position -= halfHeight;
            }

            track.style.transform = `translateY(${position}px)`;

            requestAnimationFrame(animate);
        }

        animate();
    });
})();